describe("Calendar", () => {
  const dateFormat = "MMMM yyyy";
  registerLocale("fi", fi);

  function getCalendar(
    extraProps?: Partial<
      Pick<
        CalendarProps,
        "dateFormat" | "onSelect" | "onClickOutside" | "dropdownMode"
      >
    > &
      Omit<
        CalendarProps,
        | "dateFormat"
        | "onSelect"
        | "onClickOutside"
        | "dropdownMode"
        | "showMonthYearDropdown"
      > &
      (
        | ({
            showMonthYearDropdown: true;
          } & Pick<MonthYearDropdownProps, "maxDate" | "minDate">)
        | ({
            showMonthYearDropdown?: never;
          } & Pick<YearDropdownProps, "maxDate" | "minDate"> &
            Pick<YearProps, "maxDate" | "minDate"> &
            Pick<MonthProps, "maxDate" | "minDate">)
      ),
  ) {
    let instance: Calendar | null = null;
    const { container, rerender } = render(
      <Calendar
        ref={(node) => {
          instance = node;
        }}
        dateFormat={dateFormat}
        onSelect={() => {}}
        onClickOutside={() => {}}
        dropdownMode="scroll"
        {...extraProps}
      />,
    );
    const rerenderFunc = (
      props?: Partial<Omit<CalendarProps, "showMonthYearDropdown">>,
    ) => {
      return rerender(
        <Calendar
          ref={(node) => {
            instance = node;
          }}
          dateFormat={dateFormat}
          onSelect={() => {}}
          onClickOutside={() => {}}
          dropdownMode="scroll"
          {...extraProps}
          {...props}
        />,
      );
    };
    return {
      calendar: container,
      instance: instance as unknown as Calendar | null,
      rerender: rerenderFunc,
    };
  }

  beforeAll(() => {
    setupMockResizeObserver();
  });

    return;
  };

  renderInputTimeSection = (): React.ReactElement | undefined => {
    if (!this.props.showTimeInput) {
      return;
    }

    // Handle selectsRange mode - render two time inputs
    if (this.props.selectsRange) {
      const { startDate, endDate } = this.props;

      const startTime = startDate ? new Date(startDate) : undefined;
      const startTimeValid =
        startTime && isValid(startTime) && Boolean(startDate);
      const startTimeString = startTimeValid
        ? `${addZero(startTime.getHours())}:${addZero(startTime.getMinutes())}`
        : "";

      const endTime = endDate ? new Date(endDate) : undefined;
      const endTimeValid = endTime && isValid(endTime) && Boolean(endDate);
      const endTimeString = endTimeValid
        ? `${addZero(endTime.getHours())}:${addZero(endTime.getMinutes())}`
        : "";

      return (
        <>
          <InputTime
            {...Calendar.defaultProps}
            {...this.props}
            date={startTime}
            timeString={startTimeString}
            onChange={(time: Date) => {
              this.props.onTimeChange?.(time, "start");
            }}
            timeInputLabel={(this.props.timeInputLabel ?? "Time") + " (Start)"}
          />
          <InputTime
            {...Calendar.defaultProps}
            {...this.props}
            date={endTime}
            timeString={endTimeString}
            onChange={(time: Date) => {
              this.props.onTimeChange?.(time, "end");
            }}
            timeInputLabel={(this.props.timeInputLabel ?? "Time") + " (End)"}
          />
        </>
      );
    }

    // Single date mode (original behavior)
    const time = this.props.selected
      ? new Date(this.props.selected)
      : undefined;
    const timeValid = time && isValid(time) && Boolean(this.props.selected);
    const timeString = timeValid
      ? `${addZero(time.getHours())}:${addZero(time.getMinutes())}`
      : "";
    return (
      <InputTime
        {...Calendar.defaultProps}
        {...this.props}
        date={time}
        timeString={timeString}
        onChange={(time: Date) => {
          this.props.onTimeChange?.(time);
        }}
      />
    );
  };

  renderAriaLiveRegion = (): React.ReactElement => {
    // Don't render aria-live message if date is invalid
    if (!isValid(this.state.date)) {
      return (
        <span
          role="alert"
          aria-live="polite"
          className="react-datepicker__aria-live"
        />
      );
    }

    const { startPeriod, endPeriod } = getYearsPeriod(
      this.state.date,
      this.props.yearItemNumber ?? Calendar.defaultProps.yearItemNumber,
    );
    let ariaLiveMessage;

    if (this.props.showYearPicker) {
      ariaLiveMessage = `${startPeriod} - ${endPeriod}`;
    } else if (
      this.props.showMonthYearPicker ||
      this.props.showQuarterYearPicker
    ) {
      ariaLiveMessage = getYear(this.state.date);
    } else {
      ariaLiveMessage = `${getMonthInLocale(
        getMonth(this.state.date),
        this.props.locale,
      )} ${getYear(this.state.date)}`;
    }

    return (
      <span
        role="alert"
        aria-live="polite"
        className="react-datepicker__aria-live"
      >
        {this.state.isRenderAriaLiveMessage && ariaLiveMessage}
      </span>
    );
  };

  renderChildren = (): React.ReactElement | undefined => {
    if (this.props.children) {
      return (
        <div className="react-datepicker__children-container">
          {this.props.children}
        </div>
      );
    }
    return;
  };

  render(): React.ReactElement {
    const Container = this.props.container || CalendarContainer;
    return (
      <ClickOutsideWrapper
        onClickOutside={this.handleClickOutside}
        style={{ display: "contents" }}
        ignoreClass={this.props.outsideClickIgnoreClass}
      >
        <div style={{ display: "contents" }} ref={this.containerRef}>
          <Container
            className={clsx("react-datepicker", this.props.className, {
              "react-datepicker--time-only": this.props.showTimeSelectOnly,
            })}
            showTime={this.props.showTimeSelect || this.props.showTimeInput}
            showTimeSelectOnly={this.props.showTimeSelectOnly}
            inline={this.props.inline}
          >
            {this.renderAriaLiveRegion()}
            {this.props.monthHeaderPosition === "top" &&
              this.renderPreviousButton()}
            {this.props.monthHeaderPosition === "top" &&
              this.renderNextButton()}
            {this.renderMonths()}
            {this.renderYears()}
            {this.renderTodayButton()}
            {this.renderTimeSection()}
            {this.renderInputTimeSection()}
            {this.renderChildren()}
          </Container>
        </div>
      </ClickOutsideWrapper>
    );
  }
}

import React, { type HTMLAttributes } from "react";

export interface CalendarContainerProps extends React.PropsWithChildren<
  HTMLAttributes<HTMLDivElement>
> {
